Here is the root cause:
Race condition in `walk_pmd_range()` where it assumes the PUD entry remains stable while walking PMD entries, but a concurrent thread can split a PUD leaf or refault after a split, causing the PMD table pointer to become invalid and leading to a page fault on an invalid address.

Here is the patch:

 static int walk_pmd_range(pud_t *pud, unsigned long addr, unsigned long end,
 			  struct mm_walk *walk)
 {
+	pud_t pudval = pudp_get(pud);
 	pmd_t *pmd;
 	unsigned long next;
 	const struct mm_walk_ops *ops = walk->ops;
 	bool has_handler = ops->pte_entry;
 	bool has_install = ops->install_pte;
 	int err = 0;
 	int depth = real_depth(3);

+	/*
+	 * For PTE handling, pte_offset_map_lock() takes care of checking
+	 * whether there actually is a page table. But it also has to be
+	 * very careful about concurrent page table reclaim.
+	 *
+	 * Similarly, we have to be careful here - a PUD entry that points
+	 * to a PMD table cannot go away, so we can just walk it. But if
+	 * it's something else, we need to ensure we didn't race something,
+	 * so need to retry.
+	 *
+	 * A pertinent example of this is a PUD refault after PUD split -
+	 * we will need to split again or risk accessing invalid memory.
+	 */
+	if (!pud_present(pudval) || pud_leaf(pudval)) {
+		walk->action = ACTION_AGAIN;
+		return 0;
+	}
+
 	pmd = pmd_offset(pud, addr);
 	do {
 again:
 		next = pmd_addr_end(addr, end);
 		if (pmd_none(*pmd)) {
 			if (has_install)
 				err = __pte_alloc(walk->mm, pmd);
 			else if (ops->pte_hole)
 				err = ops->pte_hole(addr, next, depth, walk);
 			if (err)
 				break;
 			if (!has_install)
 				continue;
 		}

 		walk->action = ACTION_SUBTREE;

 		/*
 		 * This implies that each ->pmd_entry() handler
 		 * needs to know about pmd_trans_huge() pmds
 		 */
 		if (ops->pmd_entry)
 			err = ops->pmd_entry(pmd, addr, next, walk);
 		if (err)
 			break;

 		if (walk->action == ACTION_AGAIN)
 			goto again;
 		if (walk->action == ACTION_CONTINUE)
 			continue;

 		if (!has_handler) { /* No handlers for lower page tables. */
 			if (!has_install)
 				continue; /* Nothing to do. */
 			/*
 			 * We are ONLY installing, so avoid unnecessarily
 			 * splitting a present huge page.
 			 */
 			if (pmd_present(*pmd) && pmd_trans_huge(*pmd))
 				continue;
 		}

 		if (walk->vma)
 			split_huge_pmd(walk->vma, pmd, addr);
 		else if (pmd_leaf(*pmd) || !pmd_present(*pmd))
 			continue; /* Nothing to do. */

 		err = walk_pte_range(pmd, addr, next, walk);
 		if (err)
 			break;

 		if (walk->action == ACTION_AGAIN)
 			goto again;

 	} while (pmd++, addr = next, addr != end);

 	return err;
 }

